/**
 * Template-based explanations. Every number comes from the comparison object; no text
 * is generated by a language model. Wording follows .kiro/steering/claims-policy.md.
 */
import type { DifferenceSummary } from "../stats/difference";
import type { OutcomeComparison, ScenarioComparison, Statement } from "./types";
import type { CostTradeoff } from "./tradeoff";

export function formatNumber(x: number): string {
  if (!Number.isFinite(x)) return "n/a";
  if (x === 0) return "0";
  const a = Math.abs(x);
  if (a >= 1e5 || a < 1e-3) return x.toExponential(3);
  return String(Number(x.toPrecision(4)));
}

const pct = (x: number) => `${(x * 100).toFixed(1)}%`;
const unitSuffix = (u: string) => (u ? ` ${u}` : "");
const ci = (d: DifferenceSummary, unit: string) =>
  `${Math.round(d.confidence * 1000) / 10}% CI [${formatNumber(d.ciLow)}, ${formatNumber(d.ciHigh)}]${unitSuffix(unit)}`;

export const INCONCLUSIVE_TEXT =
  "The interval includes zero, so under this procedure the comparison is statistically inconclusive. This is not evidence that there is no effect.";

export function explainUncertainty(o: OutcomeComparison, replications: number): string {
  const d = o.difference;
  const method = d.method === "paired-t" ? `${replications} matched replications (paired t)` : `unmatched replications (Welch t, df ≈ ${formatNumber(d.df)})`;
  switch (o.conclusion) {
    case "not-computable":
      return `${o.label}: not computable. ${d.nonFinite} replication value(s) had no observations (for example, no customers arrived in the measurement window).`;
    case "identical-in-every-replication":
      return `${o.label}: identical in every one of ${replications} matched replications, so the difference is exactly 0 under these random inputs.`;
    case "inconclusive":
      return `${o.label}: across ${method}, the ${ci(d, o.unit)} for the difference includes 0. ${INCONCLUSIVE_TEXT}`;
    default:
      return `${o.label}: across ${method}, the ${ci(d, o.unit)} for the difference excludes 0.`;
  }
}

export function explainOutcome(o: OutcomeComparison, baselineName: string, variantName: string, replications: number): Statement[] {
  const out: Statement[] = [];
  if (o.conclusion !== "not-computable") {
    const rel = o.relativeChange === null ? "" : ` (${o.relativeChange >= 0 ? "+" : ""}${pct(o.relativeChange)})`;
    const quality = o.direction === "better" ? " This is an improvement for this metric." : o.direction === "worse" ? " This is worse for this metric." : "";
    out.push({
      kind: "direct",
      metric: o.metric,
      text: `In the model, ${o.label.toLowerCase()} averages ${formatNumber(o.baselineMean)}${unitSuffix(o.unit)} in "${baselineName}" and ${formatNumber(o.variantMean)}${unitSuffix(o.unit)} in "${variantName}": a difference of ${formatNumber(o.directDifference)}${unitSuffix(o.unit)}${rel}.${quality}`,
    });
  }
  out.push({ kind: "uncertainty", metric: o.metric, text: explainUncertainty(o, replications) });
  if (o.pairing) {
    const p = o.pairing;
    const verdict =
      p.ratio < 1
        ? `Matching reduced the estimated variance of the difference by ${pct(p.varianceReduction)} compared with independent runs of the same size (ratio ${formatNumber(p.ratio)}).`
        : p.ratio > 1
          ? `Matching increased the estimated variance of the difference by ${pct(-p.varianceReduction)} compared with independent runs (ratio ${formatNumber(p.ratio)}); the matched outputs moved in opposite directions.`
          : "Matching did not change the estimated variance of the difference.";
    out.push({ kind: "pairing", metric: o.metric, text: `${o.label}: ${verdict}` });
  }
  return out;
}

export function explainComparison(cmp: Omit<ScenarioComparison, "statements" | "disclaimer">): { statements: Statement[]; disclaimer: string } {
  const st: Statement[] = [];
  if (cmp.assumptions.length === 0) st.push({ kind: "assumption", metric: null, text: "The two scenarios have identical assumptions." });
  for (const c of cmp.assumptions) {
    st.push({
      kind: "assumption",
      metric: null,
      text: `"${c.label}" changed from ${typeof c.from === "number" ? formatNumber(c.from) : String(c.from)} to ${typeof c.to === "number" ? formatNumber(c.to) : String(c.to)}${unitSuffix(c.unit)}.`,
    });
  }
  st.push({ kind: "caveat", metric: null, text: cmp.pairing.reason });
  for (const o of cmp.outcomes) st.push(...explainOutcome(o, cmp.baseline.name, cmp.variant.name, cmp.pairing.replications));

  const s = cmp.sensitivity;
  if (!s.available) {
    st.push({ kind: "caveat", metric: null, text: `One-at-a-time sensitivity analysis unavailable: ${s.reason}` });
  } else {
    for (const m of s.perMetric) {
      for (const e of m.effects) {
        const verdict = e.conclusion === "inconclusive" ? ` ${INCONCLUSIVE_TEXT}` : e.conclusion === "not-computable" ? " Not computable (no observations in some replications)." : "";
        st.push({
          kind: "model-effect",
          metric: m.metric,
          text: `Changing only "${e.label}" from ${formatNumber(e.from)} to ${formatNumber(e.to)}${unitSuffix(e.unit)}, with every other assumption at baseline, changes ${m.label.toLowerCase()} by ${formatNumber(e.effect.mean)}${unitSuffix(m.unit)} in the model (${ci(e.effect, m.unit)}).${verdict}`,
        });
      }
      if (m.effects.length > 1) {
        const i = m.interaction;
        const verdict =
          m.interactionConclusion === "inconclusive"
            ? ` ${INCONCLUSIVE_TEXT}`
            : m.interactionConclusion === "identical-in-every-replication"
              ? " The residual is 0 in every replication (within floating-point rounding): in the model the changes combine additively for this metric."
              : m.interactionConclusion === "not-computable"
                ? " Not computable."
                : " The interval excludes 0: in the model the changes do not combine additively for this metric.";
        st.push({
          kind: "interaction",
          metric: m.metric,
          text: `For ${m.label.toLowerCase()}, the combined change (${formatNumber(m.combined.mean)}${unitSuffix(m.unit)}) minus the sum of the one-at-a-time effects leaves an interaction residual of ${formatNumber(i.mean)}${unitSuffix(m.unit)} (${ci(i, m.unit)}).${verdict}`,
        });
      }
    }
    if (s.parameters.length > 1) {
      st.push({
        kind: "caveat",
        metric: null,
        text: "One-at-a-time effects plus an interaction residual are one way to decompose the combined change. They depend on the baseline chosen as the reference point, are not a unique attribution of the change to individual assumptions, and do not explain the mechanism behind an interaction.",
      });
    }
  }
  if (cmp.tradeoff) for (const text of explainTradeoff(cmp.tradeoff, cmp.baseline.name, cmp.variant.name)) st.push({ kind: "tradeoff", metric: null, text });
  st.push({
    kind: "caveat",
    metric: null,
    text: `Each interval is computed separately at ${Math.round(cmp.confidence * 1000) / 10}% confidence; across ${cmp.outcomes.length} metrics, some intervals can exclude 0 by chance alone. No multiplicity adjustment is applied.`,
  });
  const disclaimer = `These are model estimates from ${cmp.model.id}@${cmp.model.version} under its stated assumptions. They are not predictions, and they make no claim about real-world causes or effects; that would require validation against observed outcomes.`;
  return { statements: st, disclaimer };
}

/** One plain-language sentence per outcome, built only from computed fields. */
export function plainOutcome(o: OutcomeComparison, format?: (value: number, unit: string) => string): string {
  const show = format ?? ((v: number, u: string) => `${formatNumber(v)}${unitSuffix(u)}`);
  const from = show(o.baselineMean, o.unit);
  const to = show(o.variantMean, o.unit);
  const rel = o.relativeChange === null ? "" : `, ${o.relativeChange >= 0 ? "+" : ""}${pct(o.relativeChange)}`;
  switch (o.conclusion) {
    case "variant-lower":
      return `${o.label} is lower in the simulation: ${from} → ${to}${rel}.`;
    case "variant-higher":
      return `${o.label} is higher in the simulation: ${from} → ${to}${rel}.`;
    case "inconclusive":
      return `${o.label}: no clear difference in the simulation (${from} → ${to}); the result is inconclusive, not proof of no effect.`;
    case "identical-in-every-replication":
      return `${o.label} is unchanged in every simulated repeat (${from}).`;
    case "not-computable":
      return `${o.label} cannot be computed: some simulated repeats had no observations.`;
  }
}

/** "Staff on duty 2 → 3; Customers arriving 1.6 → 1.8" */
export function plainChanges(changes: readonly { label: string; from: number | string | null; to: number | string | null; unit: string }[]): string {
  if (changes.length === 0) return "No assumptions changed";
  const v = (x: number | string | null) => (typeof x === "number" ? formatNumber(x) : String(x));
  return changes.map((c) => `${c.label} ${v(c.from)} → ${v(c.to)}`).join("; ");
}

const money = (x: number) => `$${Math.abs(x) >= 100 ? x.toFixed(0) : x.toFixed(2)}`;
const signedMoney = (x: number) => `${x > 0 ? "+" : x < 0 ? "−" : ""}${money(Math.abs(x))}`;

/** Plain-language trade-off sentences. Waiting value is always described as an assumption. */
export function explainTradeoff(t: CostTradeoff, baselineName: string, variantName: string): string[] {
  const u = t.timeUnit;
  const out: string[] = [];
  out.push(
    `Staffing: "${variantName}" spends ${signedMoney(t.staffingChange.mean)} per ${u} compared with "${baselineName}" (${money(t.baselineStaffing)} → ${money(t.variantStaffing)} per ${u}).`,
  );
  const w = t.waitingHoursChange;
  out.push(
    `Waiting: customers spend ${formatNumber(Math.abs(w.mean))} ${w.mean <= 0 ? "fewer" : "more"} hours waiting per ${u} in total in the simulation (likely range ${formatNumber(w.ciLow)} to ${formatNumber(w.ciHigh)}).`,
  );
  const vText = t.waitingValue.same ? `${money(t.waitingValue.baseline)} per customer-hour` : `${money(t.waitingValue.baseline)} and ${money(t.waitingValue.variant)} per customer-hour respectively`;
  out.push(
    `If waiting is valued at the assumed ${vText}, the modelled total changes by ${signedMoney(t.netCostChange.mean)} per ${u}. That value is a hypothetical assumption, so this is not a cash saving.`,
  );
  const b = t.breakEven;
  switch (b.status) {
    case "finite": {
      const range = b.ciLow !== null && b.ciHigh !== null ? ` (likely range ${money(b.ciLow)} to ${money(b.ciHigh)}${b.intervalMethod === "delta-method" ? ", approximate" : ""})` : "";
      const who = b.preferredAbove === "variant" ? `"${variantName}"` : `"${baselineName}"`;
      out.push(`Break-even: the two options have equal modelled cost when an hour of customer waiting is worth ${money(b.value!)}${range}. Above that value ${who} costs less in the model; below it, the other option does.`);
      break;
    }
    case "variant-dominates":
      out.push(`No break-even value: in the model "${variantName}" both costs less in staffing and has less waiting.`);
      break;
    case "baseline-dominates":
      out.push(`No break-even value: in the model "${variantName}" costs more in staffing and also has more waiting.`);
      break;
    case "waiting-change-inconclusive":
      out.push("No finite break-even value: the change in waiting is statistically inconclusive, so the threshold could be anything from very small to unbounded.");
      break;
    case "no-waiting-change":
      out.push("No break-even value: total waiting does not change, so only the staffing difference matters.");
      break;
    case "no-staffing-change":
      out.push("No break-even value: staffing spending does not change, so the option with less waiting is cheaper for any positive value of waiting.");
      break;
    default:
      out.push("The trade-off cannot be computed because some results had no observations.");
  }
  return out;
}
